// fontawesome
import {faArrowRotateLeft,faCompress,faExpand,faDownload,faSquareMinus,faSquarePlus,faTable,faCode,faStop,faArrowsRotate,faPlus,faMinus,faCaretRight,faCaretDown,faAngleRight,faAngleDown} from '@fortawesome/free-solid-svg-icons'

// npm
import CSV from './lib/csv.js'

// custom
import './App.css'

// util
import * as util from './Util.js'
Object.assign(global, util)
const downloadJSON = (filename, json) => {
  var dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(json))
  var downloadAnchorNode = document.createElement('a')
  downloadAnchorNode.setAttribute("href",     dataStr)
  downloadAnchorNode.setAttribute("download", filename + ".json")
  document.body.appendChild(downloadAnchorNode)
  downloadAnchorNode.click()
  downloadAnchorNode.remove()
}

const stateFields = {
  fold: foldState,
}

const getBorderStyle = ({i, j, imax, jmax, color}) => {
  const border = `1px solid ${color}` 
  const styles = {
    left: {
      borderTop: border,
    },
    right: {
      borderLeft: border,
      borderTop: border,
    },
    top: {
      borderLeft: border,
    },
    bot: {
      borderLeft: border,
      borderTop: border,
    },
    topLeft: {
    },
    topRight: {
      borderLeft: border,
    },
    botLeft: {
      borderTop: border,
    },
    botRight: {
      borderLeft: border,
      borderTop: border,
    },
    center: {
      borderLeft: border,
      borderTop: border,
    },
  }
  const style = (
    i==0 && j==0             ? styles.topLeft  :
    i==imax && j==0          ? styles.topRight :
    i==0 && j==jmax          ? styles.botLeft  :
    i==imax && j==jmax       ? styles.botRight :
    i==0 && j>0 && j<jmax    ? styles.left     :
    i==imax && j>0 && j<jmax ? styles.right    :
    j==0                     ? styles.top      :
    j==jmax                  ? styles.bot      :
                              styles.center
  )
  return style
}

const VTable3 = ({tableData, showHeader}) => {
  if (tableData == null)
    return <div style={{height: '600px'}} />

  const {columns, data} = tableData

  const table = useReactTable({
    data,
    columns,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    debugTable: false,
  })

  const { rows } = table.getRowModel()

  const tableContainerRef = useRef(null)

  const rowVirtualizer = useVirtualizer({
    count: rows.length,
    estimateSize: () => 19,
    getScrollElement: () => tableContainerRef.current,
    measureElement:
      typeof window !== 'undefined' &&
      navigator.userAgent.indexOf('Firefox') === -1
        ? element => element?.getBoundingClientRect().height
        : undefined,
    overscan: 5,
  })

  const imax = columns.length-1
  const jmax = rows.length-1

  return (
    <div
      className={`container ${showHeader ? 'header' : ''}`}
      ref={tableContainerRef}
      // style={containerStyle}
    >
      <table style={{ display: 'grid' }}>
        <thead
          style={{
            display: 'grid',
            position: 'sticky',
            top: 0,
            zIndex: 1,
          }}
        >
          {true && (
            table.getHeaderGroups().map(headerGroup => (
              <tr
                key={headerGroup.id}
                style={{ display: 'flex', width: '100%' }}
              >
                {headerGroup.headers.map(header => {
                  const thStyle = {
                    display: 'flex',
                    width: showHeader ? header.getSize() : '16px',
                    marginTop: showHeader ? 0 : `-${header.column.columnDef.size+2}px`,
                  }
                  return (
                    <th
                      key={header.id}
                      style={thStyle}
                    >
                      <div
                        {...{
                          className: header.column.getCanSort()
                            ? 'cursor-pointer select-none'
                            : '',
                          style: {textAlign: 'center', display: 'flex'},
                        }}
                      >
                        <span style={{
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          width: '100%',
                        }}>
                          {flexRender(
                            header.column.columnDef.header,
                            header.getContext()
                          )}
                        </span>
                      </div>
                    </th>
                  )
                })}
              </tr>
            ))
          )}
        </thead>
        <tbody
          style={{
            display: 'grid',
            height: `${rowVirtualizer.getTotalSize()}px`,
            position: 'relative',
          }}
        >
          {rowVirtualizer.getVirtualItems().map(virtualRow => {
            const row = rows[virtualRow.index]
            return (
              <tr
                data-index={virtualRow.index}
                ref={node => rowVirtualizer.measureElement(node)}
                key={row.id}
                style={{
                  display: 'flex',
                  position: 'absolute',
                  transform: `translateY(${virtualRow.start}px)`,
                  width: '100%',
                }}
              >
                {row.getVisibleCells().map(cell => {
                  const style = getBorderStyle({
                    i: cell.column.columnDef.index,
                    j: cell.row.index,
                    imax: imax,
                    jmax: jmax,
                    color: '#acacac',
                  })
                  style.display = 'flex'
                  style.width = cell.column.getSize()
                  if (showHeader)
                    style.minHeight = '19px'
                  else {
                    style.width = '16px'
                    style.height = '16px'
                    style.display = 'inline-block'
                    style.textAlign = 'center'
                    style.verticalAlign = 'middle'
                  }
                  
                  const className = cell.getValue() == '' ? 'empty' : 'filled'
                  return (
                    <td
                      key={cell.id}
                      style={style}
                      className={className}
                    >
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext()
                      )}
                    </td>
                  )
                })}
              </tr>
            )
          })}
        </tbody>
      </table>
    </div>
  )
}

// code folding
function foldAllRecursive(view, fold) {
  const state = view.state

  // Traverse the syntax tree and collect all foldable ranges
  const foldRanges = []
  syntaxTree(state).iterate({
    enter(node) {
      const isFoldable = foldable(state, node.from, node.to)
      if (isFoldable)
        foldRanges.push({ from: isFoldable.from, to: isFoldable.to });
    }
  })

  // fold or unfold all
  const effect = fold ? foldEffect : unfoldEffect
  view.dispatch({
    effects: foldRanges.map(range => effect.of({ from: range.from, to: range.to }))
  })
}
function unfoldAll(view) {
  foldAllRecursive(view, false)
}
function foldAll(view) {
  foldAllRecursive(view, true)
}
function foldRanges(view, ranges) {
  const state = view.state
  unfoldAll(view)

  // find ranges to fold
  const foldRanges = []
  syntaxTree(state).iterate({
    enter(node) {
      const isFoldable = foldable(state, node.from, node.to)
      if (isFoldable) {
        const inRanges = ranges.some(r => r[0] == isFoldable.from && r[1] == isFoldable.to)
        if (inRanges)
          foldRanges.push({from: isFoldable.from, to: isFoldable.to})
      }
    }
  })

  // fold
  view.dispatch({
    effects: foldRanges.map(r => foldEffect.of({ from: r.from, to: r.to }))
  })
}

export default function Code({id, title, folds0, src0, src, initState, extensions=[], sink=false, csv=false, csvheader=true, highlight, error=null, minimized, winstyle={}, maxHeight='100vh', evaluating=null}) {
  // util
  const key = (attr) => `${id}_${attr}`
  const get = (attr) => localStorage.getItem(key(attr))
  const set = (attr,val) => localStorage.setItem(key(attr), val)
  const getj = (attr) => JSON.parse(get(attr))
  const setj = (attr,val) => set(attr, JSON.stringify(val))

  // global
  const {fullscreenWin} = useContext(GlobalContext)

  // state
  const windowRef = useRef(null)
  const editor = useRef()
  const [hover, setHover] = useState(false)
  const tableView = useStore(key('csv'), csv)
  const draggableRef = useRef()
  const {events} = useDraggable(draggableRef, {
    isMounted: !minimized.val && tableView.val,
    applyRubberBandEffect: false,
    decayRate: 0,
  })
  const fullscreend = fullscreenWin?.val == windowRef

  // vtable3
  const tableData = useMemo(
    () => {
      if (!csv)
        return null
      const csvSrc = src.val

      // empty check
      if (csvSrc == null || csvSrc == '')
        return null

      // parse csv
      var lines = []
      var headers = []
      var rows = []
      try {
        lines = CSV.parse(csvSrc)
        headers = csvheader ? lines[0]
                            : range(lines[0].length).map(i => `h_${i}`)
        rows = csvheader ? lines.slice(1)
                          : lines
      }
      catch (e) {
        log('CANT PARSE CSV')
        log(e)
        return null
      }

      const columns = headers.map((h,idx) => {
        const size = (
          !csvheader            ? 16  :
          h=='Sets'             ? 40  :
          h=='Reps'             ? 40  :
          h=='Weeks in Program' ? 60  :
          h=='Days/Week'        ? 80  :
          h=='Equipment'        ? 80  :
          h=='Week/Day Name'    ? 80  :
          h=='Description'      ? 500 :
                                  null
        )
        const col = {
          id: h,
          index: idx,
          accessorKey: h,
          header: () => h,
          cell: info => info.getValue(),
        }
        if (size != null)
          col.size = size
        
        return col
      })

      const data = []
      rows.forEach(row => {
        const datum = {}
        for (var i = 0; i < headers.length; i++) {
          const val = row[i] == null ? '' : row[i]
          datum[headers[i]] = val
        }
        data.push(datum)
      })

      return {columns, data}
    },
    [src.val],
  )

  // codemirror
  const {setContainer, setState, view} = useCodeMirror({
    initialState: initState,
    onChange: (value, viewUpdate) => {
      // setSrc(value)
      // set('src', value)
      src.set(value)
    },
    onUpdate: (viewUpdate) => {
      const state = viewUpdate.state.toJSON(stateFields)
      setj('state', state)
    },
    extensions: extensions,
    container: editor.current,
    maxHeight: maxHeight,
  })

  // unnecessary?
  useEffect(() => {
    if (editor.current) {
      setContainer(editor.current)
    }
  }, [editor.current])
  
  // sink set
  useEffect(() => {
    if (sink && view != null && !view.hasFocus) {
      view.dispatch({changes: {
        from: 0,  
        to: view.state.doc.length,
        insert: src.val
      }})
    }
  }, [view, src.val])

  // tool callbacks
  const onToggleTableView = useCallback(() => tableView.set(!tableView.val),
    [tableView.val])
  const onMinimize = useCallback(() => minimized.set(!minimized.val), 
    [minimized.val])
  const onReset = useCallback(() => {
    if (view == null)
      return
    
    // view
    view.dispatch({changes: {
      from: 0,
      to: view.state.doc.length,
      insert: src0
    }})
    foldRanges(view, folds0)

    // store

    localStorage.removeItem(key('src'))
    localStorage.removeItem(key('state'))

    // state
    // setSrc(src0)
    src.reset()
  }, [src.val, view])
  const onUnfoldAll = useCallback(() => {
    unfoldAll(view)
  }, [view])
  const onFoldAll = useCallback(() => {
    foldAll(view)
  }, [view])
  const onDownload = useCallback(() => {
    log(id, view.state.toJSON(stateFields))
    const json = view.state.toJSON(stateFields)
    downloadJSON(key('state'), json)
  }, [view])
  const onFullscreen = useCallback(() => {
    const val = fullscreenWin.val == windowRef ? null
                                               : windowRef
    fullscreenWin.set(val)
  }, [fullscreenWin.val])

  const showFoldTools = extensions.length > 0
  const tools = {
    minimize:   toolButton({
                  id: 'minimize',
                  title: minimized.val ? 'Show' : 'Hide',
                  icon:  minimized.val ? faAngleRight : faAngleDown,
                  click: onMinimize,
                  invert: highlight.val,
                }),
    viewToggle: toolButton({
                  id: 'viewToggle',
                  title: tableView.val ? 'View CSV' : 'View Table',
                  icon:  tableView.val ? faCode : faTable,
                  click: onToggleTableView,
                  invert: highlight.val,
                }),
    unfold:     toolButton({
                  id: 'unfold',
                  title: 'Unfold All',
                  icon:  faExpand,
                  click: onUnfoldAll,
                  invert: highlight.val,
                }),
    fold:       toolButton({
                  id: 'fold',
                  title: 'Fold All',
                  icon:  faCompress,
                  click: onFoldAll,
                  invert: highlight.val,
                }),
    reset:      toolButton({
                  id: 'reset',
                  title: 'Reset',
                  icon:  faArrowRotateLeft,
                  click: onReset,
                  invert: highlight.val,
                }),
    download:   toolButton({
                  id: 'download',
                  title: 'Download',
                  icon:  faDownload,
                  click: onDownload,
                  invert: highlight.val,
                }),
    stop:       toolButton({
                id: 'stop',
                  title: 'Stop',
                  icon:  faStop,
                  invert: highlight.val,
                  // click: onDownload,
                }),
    evaling:    toolButton({
                id: 'evaling',
                  title: 'Evaluating...',
                  icon:  faArrowsRotate,
                  iconClass: 'spin',
                }),
    fullscreen:    toolButton({
                  id: 'fullscreen',
                  title: fullscreend ? 'Shrink' : 'Maximize',
                  icon:  fullscreend ? faCompress : faExpand,
                  click: onFullscreen,
                }),
  }

  const overlayStyle = windowRef.current != null ? {
    width: windowRef.current.clientWidth,
    height: windowRef.current.clientHeight,
    marginTop: -windowRef.current.clientHeight,
  } : {}

  const evalStyle = evaluating?.val ? {
    animation: 'pulse 0.4s infinite',
  } : {}

  const rootStyle = fullscreend ? {
    // ...winstyle,
    position: 'fixed',
    zIndex: 100,
    left: 50,
    right: 50,
    top: 50,
    bottom: 50,
  } : winstyle
  const titleStyle = fullscreend ? {
    paddingLeft: '4px',
    paddingRight: '4px',
  } : {
    paddingRight: '4px',
  }

  return (
    <div
      ref={windowRef}
      className={`window code ${highlight.val ? 'highlight' : ''} ${error?.val ? 'highlight-error' : ''} ${fullscreend ? 'fullscreen' : ''}`}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={rootStyle}
    >
      <div className={`titlebar code ${minimized.val ? 'minimized' : ''} ${highlight.val ? 'highlight' : ''} ${error?.val ? 'highlight-error' : ''}`}>
        {!fullscreend &&
          tools.minimize}
        <span className='title' style={titleStyle}>
          {title}
        </span>
        {sink && evaluating?.val ?
          tools.evaling
          : (
          (hover && !minimized.val && !error.val &&
            <div className='toolrow'>
              {csv && 
                tools.viewToggle}
              {showFoldTools && 
                tools.unfold}
              {showFoldTools && 
                tools.fold}
              {!sink && (!tableView.val || !csv) &&
                tools.reset}
              {tools.fullscreen}
              {/* {tools.download} */}
              {/* {tools.stop} */}
            </div>)
          )}
      </div>
      <div
        ref={draggableRef}
        className='windowBody'
        style={evalStyle}
        {...events}
      >
        {!minimized.val && !error?.val &&
          (csv ?
            (tableView.val ?//&& error?.val != true ?
              <VTable3 
                tableData={tableData}
                showHeader={csvheader}
              /> :
              <div ref={editor}/>) :
            <div ref={editor}/>)
        }
        {!minimized.val && error?.val &&
          <p><code style={{color: '#ff002b', margin: '5px', fontSize: '12px', lineHeight: '14px'}}>{src.val}</code></p>}
      </div>
      {highlight.val && 
        <div className='overlay' style={overlayStyle} />}
    </div>
  )
}