export default "using Jint;\r\nusing Jint.Runtime;\r\nusing Jint.Runtime.Interop;\r\nusing System;\r\nusing System.IO;\r\nusing System.Linq;\r\nusing System.Threading;\r\nusing System.Collections;\r\nusing System.Collections.Generic;\r\nusing UnityEngine;\r\nusing UnityEngine.Networking;\r\nusing UnityEngine.SceneManagement;\r\n\r\n#if UNITY_EDITOR\r\nusing UnityEditor;\r\nusing NativeWebSocket;\r\n#endif\r\n\r\nusing Newtonsoft.Json;\r\n\r\nusing v2 = UnityEngine.Vector2;\r\nusing v3 = UnityEngine.Vector3;\r\nusing Gob = UnityEngine.GameObject;\r\nusing Body = UnityEngine.Rigidbody;\r\n\r\npublic class FileUpdate {\r\n\tpublic string file;\r\n\tpublic string text;\r\n}\r\npublic class ExecutionCancelledException : Exception {}\r\nclass ThrottleConstraint : Jint.Constraint {\r\n\tjsrun runner;\r\n\tint runCounter = 0;\r\n\r\n\tpublic ThrottleConstraint(jsrun j) {\r\n\t\trunner = j;\r\n\t}\r\n  public override void Reset() {}\r\n  public override void Check() {\r\n    runner.GetMessages();\r\n    if (runner.editCount > 1)\r\n      throw new ExecutionCancelledException();\r\n  }\r\n}\r\n\r\npublic class jsrun : MonoPlus {\r\n\t[Header(\"Values\")]\r\n\tpublic bool serverEnabled;\r\n\tpublic float jsTimeout = 10f;\r\n  \r\n\t[Header(\"Objects\")]\r\n\tpublic Button devSettingsButton;\r\n\tpublic Button devSettingsCloseButton;\r\n\tpublic GameObject devSettingsPanel;\r\n\tpublic TMP_InputField serverAddressInput;\r\n\tpublic TMP_InputField serverPortInput;\r\n\tpublic TMP_InputField fileServerPortInput;\r\n\r\n  ////////\r\n  // STATE\r\n  ////////\r\n\tpublic static jsrun jsrunInstance;\r\n\tCancellationTokenSource cancelSource;\r\n\tEngine engine;\r\n  #if UNITY_EDITOR\r\n\tWebSocket websocket;\r\n  #endif\r\n\tDictionary<string,string> codes;\r\n\tpublic bool editDirty = false;\r\n\tList<Gob> globalObjectPool = new();\r\n\tpublic int editCount = 0;\r\n\tFileUpdate latestUpdate;\r\n\tpublic string hotScenePath;\r\n\r\n  ////////////////\r\n  // GAME SPECIFIC\r\n  ////////////////\r\n\tHashSet<string> englishWords;\r\n\tvoid LoadEnglishWords() {\r\n\t\tstring dictPath = \"dictionary/words_alpha\";\r\n\t\tstring text = Resources.Load<TextAsset>(dictPath).text;\r\n\t\tList<string> words = text.Split(new string[] { \"\\r\\n\" }, StringSplitOptions.None).ToList();//text.Split('\\n').ToList();\r\n\t\tenglishWords = new HashSet<string>(words);\r\n\t\tlog(englishWords.Count);\r\n\t}\r\n\tpublic bool IsValidWord(string word) {\r\n\t\treturn englishWords.Contains(word);\r\n\t}\r\n\r\n  ////////////\r\n  // EVALUATOR\r\n  ////////////\r\n\tpublic void InitEngine() {\r\n\t\tcancelSource = new CancellationTokenSource();\r\n\t\tengine = new Engine(options => {\r\n\t\t\toptions.AddExtensionMethods(typeof(Vector3Extension));\r\n\t\t\toptions.AddExtensionMethods(typeof(Vector2Extension));\r\n\t\t\toptions.AddExtensionMethods(typeof(GameObjectExtension));\r\n\t\t\toptions.AddExtensionMethods(typeof(ColorExtension));\r\n\t\t\toptions.AllowClr();\r\n\t\t\t// options.CancellationToken(cancelSource.Token);\r\n\t\t\toptions.TimeoutInterval(TimeSpan.FromSeconds(jsTimeout));\r\n\t\t\toptions.Constraint(new ThrottleConstraint(this));\r\n\t\t});\r\n\t\tvar types = new List<Type>() {\r\n\t\t\ttypeof(SceneManager),\r\n\t\t\ttypeof(Screen),\r\n\t\t\ttypeof(Input),\r\n\t\t\ttypeof(Time),\r\n\t\t\ttypeof(Gob),\r\n\t\t\ttypeof(Physics),\r\n\t\t\ttypeof(Transform),\r\n\t\t\ttypeof(Scene),\r\n\r\n\t\t\t// enums\r\n\t\t\ttypeof(PrimitiveType),\r\n\t\t\ttypeof(TouchPhase),\r\n\t\t\ttypeof(ForceMode),\r\n\t\t\ttypeof(RuntimePlatform),\r\n\t\t\ttypeof(CursorLockMode),\r\n\t\t\ttypeof(Space),\r\n\t\t\ttypeof(HapticStrength),\r\n\t\t\ttypeof(KeyCode),\r\n\t\t\ttypeof(FontStyle),\r\n\t\t\ttypeof(Motion),\r\n\t\t\ttypeof(RenderTextureFormat),\r\n\r\n\t\t\t// components\r\n\t\t\ttypeof(Camera),\r\n\t\t\ttypeof(Mesh),\r\n\t\t\ttypeof(MeshFilter),\r\n\t\t\ttypeof(Color),\r\n\t\t\ttypeof(Texture),\r\n\t\t\ttypeof(Texture2D),\r\n\t\t\ttypeof(Sprite),\r\n\t\t\ttypeof(Material),\r\n\t\t\ttypeof(MeshRenderer),\r\n\t\t\ttypeof(SpriteRenderer),\r\n\t\t\ttypeof(LineRenderer),\r\n\t\t\ttypeof(Collider),\r\n\t\t\ttypeof(BoxCollider),\r\n\t\t\ttypeof(SphereCollider),\r\n\t\t\ttypeof(CapsuleCollider),\r\n\t\t\ttypeof(MeshCollider),\r\n\r\n\t\t\t// ui components\r\n\t\t\ttypeof(EventSystem),\r\n\t\t\ttypeof(GraphicRaycaster),\r\n\t\t\ttypeof(Image),\r\n\t\t\ttypeof(RawImage),\r\n\t\t\ttypeof(Slider),\r\n\r\n\t\t\t// misc\r\n\t\t\ttypeof(Quaternion),\r\n\t\t\ttypeof(v3),\r\n\t\t\ttypeof(v2),\r\n\t\t\ttypeof(Ray),\r\n\t\t\ttypeof(RaycastHit),\r\n\t\t\ttypeof(Mathf),\r\n\t\t\ttypeof(Debug),\r\n\t\t\ttypeof(Application),\r\n\t\t\ttypeof(Touch),\r\n\t\t\ttypeof(LineUtility),\r\n\t\t\ttypeof(Rect),\r\n\t\t\ttypeof(Bounds),\r\n\t\t\ttypeof(TextureFormat),\r\n\t\t\ttypeof(RenderTexture),\r\n\t\t\ttypeof(Cursor),\r\n\t\t\ttypeof(VideoPlayer),\r\n\t\t\ttypeof(Resources),\r\n\r\n\t\t\t// custom\r\n\t\t\ttypeof(jsrun),\r\n\t\t\ttypeof(Util),\r\n\t\t\ttypeof(Tool),\r\n\t\t\ttypeof(Motion),\r\n\r\n\t\t\t// 3rd party\r\n\t\t\ttypeof(CatmullRom),\r\n\t\t\ttypeof(PolygonColliderOptimizer),\r\n\t\t\ttypeof(CollisionListener),\r\n\t\t\ttypeof(MacTrackpad),\r\n\t\t\ttypeof(MacTouchPhase),\r\n\r\n\t\t\t// Editor\r\n\t\t\t#if UNITY_EDITOR\r\n\t\t\ttypeof(SceneView),\r\n\t\t\t#endif\r\n\t\t};\r\n\r\n\t\ttypes.ForEach(t => {\r\n\t\t\tstring name = t.ToString().Split('.').Last();\r\n\t\t\tengine.SetValue(name, TypeReference.CreateTypeReference(engine, t));\r\n\t\t});\r\n\r\n\t\t// cleanup\r\n\t\tengine.SetValue(\"globalObjectPool\", globalObjectPool);\r\n\r\n\t\tengine.SetValue(\"V2List\", TypeReference.CreateTypeReference(engine, typeof(List<v2>)));\r\n\t\tengine.SetValue(\"V3List\", TypeReference.CreateTypeReference(engine, typeof(List<v3>)));\r\n\t\tengine.SetValue(\"Random\", TypeReference.CreateTypeReference(engine, typeof(UnityEngine.Random)));\r\n\r\n\t\tengine.SetValue(\"o\", new Func<string,Gob>(name => o(name)));\r\n\t\tengine.SetValue(\"log\", new Action<object>(msg => log(msg)));\r\n\t\tengine.SetValue(\"Instantiate\", new Func<UnityEngine.Object, UnityEngine.Object>(o => Instantiate(o)));\r\n\t\tengine.SetValue(\"Destroy\", new Action<UnityEngine.Object>(o => Destroy(o)));\r\n\t\tengine.SetValue(\"Raycast\", new Func<Ray, float, int, _RaycastHit>((r,l,m) => Raycast(r,l,m)));\r\n\t\tengine.SetValue(\"GetCollision\", new Func<float, _Collision>((f) => CollisionMarshal.GetCollision(f)));\r\n\r\n\t\t// app methods, app values\r\n\t\tengine.SetValue(\"AddButtonCallback\", new Action<Gob>((g) => AddButtonCallback(g)));\r\n\t\tengine.SetValue(\"MakeRenderTexture\", new Func<int,int,RenderTexture>((w,h) => new RenderTexture(w,h,16)));\r\n\t\tengine.SetValue(\"MakeBounds\", new Func<v3,v3,Bounds>((center,size) => new Bounds(center,size)));\r\n\t\tengine.SetValue(\"TestInt\", new Func<int,int>((i) => TestInt(i)));\r\n\t\tengine.SetValue(\"MakeTexture\", new Func<int,int,Texture2D>((w,h) => MakeTexture(w,h)));\r\n\t\tengine.SetValue(\"MakeSprite\", new Action<int>((_) => MakeSprite()));\r\n\r\n\t\t// Words Game specific\r\n\t\tengine.SetValue(\"IsValidWord\", new Func<string,bool>((word) => IsValidWord(word)));\r\n\t\tengine.SetValue(\"Reload\", new Action<int>((x) => Reload()));\r\n\r\n\t\t// resources\r\n\t\tengine.SetValue(\"LoadTexture2D\", new Func<string, UnityEngine.Texture2D>((path) => {\r\n\t\t\tvar tex = Resources.Load<Texture2D>(path);\r\n\t\t\treturn tex;\r\n\t\t}));\r\n\t\tengine.SetValue(\"LoadAsyncTexture2D\", new Action<string, OnLoadTexture2D>((path, cb) => {\r\n\t\t\tIEnumerator _() {\r\n\t\t\t\tvar request = Resources.LoadAsync<Texture2D>(path);\r\n\t\t\t\twhile (!request.isDone)\r\n\t\t\t\t\tyield return null;\r\n\t\t\t\tif (cb != null)\r\n\t\t\t\t\tcb((Texture2D)request.asset);\r\n\t\t\t}\r\n\t\t\tStartCoroutine(_());\r\n\t\t}));\r\n\t}\r\n\tvoid Execute(string code) {\r\n\t\tvar body = \"\";\r\n    try {\r\n      body = code;\r\n      engine.Execute(body);\r\n    }\r\n    catch (JavaScriptException ex) {\r\n      Debug.LogError($\"{ex.Location} -- {ex.JavaScriptStackTrace} -- {ex.Error}\");\r\n    }\r\n\t\tcatch (ExecutionCancelledException ex) {\r\n\t\t\tthrow new ExecutionCancelledException();\r\n\t\t}\r\n    catch (Exception ex) {\r\n      Debug.LogError($\"JS App Error: {ex.Message}\\n\");\r\n    }\r\n\t}\r\n\tvoid QueueMessage(string msg) {\r\n\t\tFileUpdate update = JsonConvert.DeserializeObject<FileUpdate>(msg);\r\n\t\tlatestUpdate = update;\r\n\t\teditCount++;\r\n\t}\r\n\tstring ProcessCode(string code) {\r\n\t\treturn code.Split(\"---\")[0];\r\n\t}\r\n\tvoid ProcessEdit() {\r\n\t\tGetMessages();\r\n\t\tif (editCount > 0) {\r\n\t\t\tstring code = ProcessCode(latestUpdate.text);\r\n\t\t\tcodes[latestUpdate.file] = code;\r\n\t\t\tReload();\r\n\t\t}\r\n\t\teditCount = 0;\r\n\t}\r\n  void LoadCodes() {\r\n\t\tstring utilPath = \"js/src/util\";\r\n\t\tstring mainPath = \"js/src/main\";\r\n\t\tcodes = new Dictionary<string,string>() {\r\n\t\t\t{\"util\", ProcessCode(Resources.Load<TextAsset>(utilPath).text)},\r\n\t\t\t{\"main\", ProcessCode(Resources.Load<TextAsset>(mainPath).text)},\r\n\t\t};\r\n\t}\r\n\tpublic void Reload() {\r\n\t\tCleanup();\r\n\t\tClearLog();\r\n\t\tInitEngine();\r\n\t}\r\n\tvoid Cleanup() {\r\n\t\tforeach (var gob in globalObjectPool) {\r\n\t\t\tDestroy(gob);\r\n\t\t}\r\n\t\tglobalObjectPool.Clear();\r\n\t}\r\n\r\n  /////////////////\r\n  // HOTLOAD SERVER\r\n  /////////////////\r\n  void OnDevSettingsButton() {\r\n\t\tdevSettingsPanel.On();\r\n\t}\r\n\tvoid OnDevSettingsCloseButton() {\r\n\t\tdevSettingsPanel.Off();\r\n\t}\r\n\tvoid OnServerAddressChange(string addr) {\r\n\t\tUtil.String(\"serverAddress\", addr);\r\n\t\t#if UNITY_EDITOR\r\n\t\tConnectToServer();\r\n\t\t#endif\r\n\t}\r\n\tvoid OnServerPortChange(string port) {\r\n\t\tUtil.String(\"serverPort\", port);\r\n\t\t#if UNITY_EDITOR\r\n\t\tConnectToServer();\r\n\t\t#endif\r\n\t}\r\n\tvoid OnFileServerPortChange(string port) {\r\n\t\tUtil.String(\"fileServerPort\", port);\r\n\t}\r\n  #if UNITY_EDITOR\r\n\tasync void ConnectToServer() {\r\n\t\tstring addr = \"ws://\"+serverAddressInput.text+\":\"+serverPortInput.text;\r\n\t\tLog(\"ConnectToServer: \"+addr);\r\n\t\twebsocket = new WebSocket(addr);\r\n\r\n\t\twebsocket.OnMessage += (bytes) => {\r\n\t\t\tstring msg = System.Text.Encoding.UTF8.GetString(bytes);\r\n\t\t\tQueueMessage(msg);\r\n\t\t};\r\n\r\n\t\twebsocket.OnError += async (e) => {\r\n\t\t\tDebug.Log(\"Error! \" + e);\r\n\t\t\tawait websocket.Close();\r\n\t\t};\r\n\r\n\t\twebsocket.OnOpen += () => {\r\n\t\t\tLog(\"Connection open! \" + websocket.State);\r\n\t\t\tCancelInvoke();\r\n\r\n\t\t\twebsocket.OnClose += (e) => {\r\n\t\t\t\tLog(\"Connection closed!\");\r\n\t\t\t\tInvokeRepeating(\"ConnectToServer\", 1f, 1f);\r\n\t\t\t};\r\n\t\t};\r\n\r\n\t\t// waiting for messages\r\n\t\tawait websocket.Connect();\r\n  }\r\n  #endif\r\n\tvoid Reconnect() {\r\n\t\tLog(\"reconnect\");\r\n\t\twebsocket.Close();\r\n\t\twebsocket.Connect();\r\n\t}\r\n\tasync void OnDisconnect() {\r\n\t\tInvokeRepeating(\"TryReconnect\", 0f, 1f);\r\n\t\tawait websocket.Close();\r\n\t\tInvoke(\"ConnectToServer\", 1f);\r\n\t}\r\n\tvoid TryReconnect() {\r\n\t\tif (websocket != null && websocket.State == WebSocketState.Open) {\r\n\t\t\tCancelInvoke();\r\n\t\t\treturn;\r\n\t\t}\r\n\t\tReconnect();\r\n\t}\r\n  #if UNITY_EDITOR\r\n\tasync void Send(string result) {\r\n\t\tif (websocket.State == WebSocketState.Open) {\r\n\t\t\tawait websocket.SendText(result);\r\n\t\t}\r\n\t}\r\n\tasync void OnApplicationQuit() {\r\n\t\tif (websocket != null)\r\n\t\t\tawait websocket.Close();\r\n\t}\r\n  #endif\r\n\tvoid GetMessages() {\r\n\t\t#if UNITY_EDITOR\r\n\t\tif (serverEnabled && websocket != null)\r\n\t\t\twebsocket.DispatchMessageQueue();\r\n\t\t#endif\r\n\t}\r\n\r\n  ///////////////\r\n  // UNITY EVENTS\r\n  ///////////////\r\n  public override void Init() {\r\n\t\tbase.Init();\r\n\r\n\t\t// Words Game specific\r\n\t\tLoadEnglishWords();\r\n\r\n\t\tLoadCodes();\r\n\t\tInitEngine();\r\n\r\n\t\t// dev settings\r\n\t\t#if UNITY_EDITOR\r\n\t\t\tstring addr = \"localhost\";\r\n\t\t#else\r\n\t\t\tstring addr = \"192.168.0.102\";\r\n\t\t#endif\r\n\t\tserverAddressInput.text = Util.GString(\"serverAddress\", addr);\r\n\t\tserverPortInput.text = Util.GString(\"serverPort\", \"8765\");\r\n\t\tfileServerPortInput.text = Util.GString(\"serverPort\", \"8000\");\r\n\t\tdevSettingsButton.onClick.AddListener(OnDevSettingsButton);\r\n\t\tdevSettingsCloseButton.onClick.AddListener(OnDevSettingsCloseButton);\r\n\t\tserverAddressInput.onValueChanged.AddListener(OnServerAddressChange);\r\n\t\tserverPortInput.onValueChanged.AddListener(OnServerPortChange);\r\n\t\tfileServerPortInput.onValueChanged.AddListener(OnFileServerPortChange);\r\n\r\n\t\tif (serverEnabled) {\r\n\t\t\tInvokeRepeating(\"ConnectToServer\", 0f, 1f);\r\n\t\t}\r\n\t}\r\n\tvoid Update() {\r\n\t\tProcessEdit();\r\n\t\t\r\n\t\t// editor input\r\n\t\tif (Input.GetKey(KeyCode.C)) {\r\n\t\t\tClearLog();\r\n\t\t}\r\n\t\tif (Input.GetKey(KeyCode.P)) {\r\n\t\t\tDebug.Break();\r\n\t\t}\r\n\t\tif (Input.GetKey(KeyCode.R)) {\r\n\t\t\tReload();\r\n\t\t\treturn;\r\n\t\t}\r\n\t\t\r\n\t\tif (editCount == 0)\r\n\t\t\tExecute(\"update()\");\r\n\t}\r\n\tvoid LateUpdate() {\r\n\t\tif (editCount == 0)\r\n\t\t\tExecute(\"late_update()\");\r\n\t}\r\n}";