// react
import {useState, useCallback, useEffect, useRef, useMemo, useContext} from 'react'

// fontawesome
import {faArrowRotateLeft,faCompress,faExpand,faDownload,faSquareMinus,faSquarePlus,faTable,faCode,faStop,faArrowsRotate,faPlus,faMinus,faAngleRight,faAngleDown} from '@fortawesome/free-solid-svg-icons'

// custom
import './App.css'

// util
import * as util from './Util.js'
Object.assign(global, util)

export default function Win({id=null, title, addTools, content, minimizable=true, highlight=null, evaluating=false, evaluatingTooltip='Loading...', winref=null, winbodystyle={}}) {
  if (id == null) id = title

  // util
  const key = (attr) => `Win_${title}_${attr}`
  
  // global
  const {fullscreenWin} = useContext(GlobalContext)

  // state
  const winref1 = winref == null ? useRef(null)
                                 : winref
  const minimized = useStore(key('minimized'), false)
  const [hover, setHover] = useState(false)
  const fullscreend = fullscreenWin?.val == winref1

  // tool callbacks
  const onMinimize = useCallback(() => minimized.set(!minimized.val), 
    [minimized.val])
  const onFullscreen = useCallback(() => {
    const val = fullscreenWin.val == winref1 ? null
                                             : winref1
    fullscreenWin.set(val)
  }, [fullscreenWin.val])

  // const activeTools = tools.filter(t => t.active)
  const tools = {
    minimize:   toolButton({
                  id: 'minimize',
                  title: minimized.val ? 'Show' : 'Hide',
                  icon:  minimized.val ? faAngleRight : faAngleDown,
                  click: onMinimize,
                }),
    evaling:    toolButton({
                  id: 'evaling',
                  title: evaluatingTooltip,
                  icon:  faArrowsRotate,
                  iconClass: 'spin',
                }),
    fullscreen:    toolButton({
                  id: 'fullscreen',
                  title: fullscreend ? 'Shrink' : 'Expand',
                  icon:  fullscreend ? faCompress : faExpand,
                  click: onFullscreen,
                }),
  }
  
  const overlayStyle = winref1.current != null ? {
    width: winref1.current.clientWidth,
    height: winref1.current.clientHeight,
    marginTop: -winref1.current.clientHeight,
  } : {}

  const rootStyle = fullscreend ? {
    position: 'fixed',
    zIndex: 100,
    // left: 50,
    // right: 50,
    top: 50,
    bottom: 50,
    aspectRatio: 1/1,
  } : {}
  const titleStyle = fullscreend ? {
    paddingLeft: '4px',
    paddingRight: '4px',
  } : {
    paddingRight: '4px',
  }
  const bodyStyle = fullscreend ? {
    width: '100%',
    height: '100%,'
  } : {
    ...winbodystyle,
    overflow: 'hidden',
  }

  return (
    <div
      ref={winref1}
      className={`window ${highlight?.val ? 'highlight' : ''} ${fullscreend ? 'fullscreen' : ''}`}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={rootStyle}
    >
      <div className={`titlebar ${minimized ? 'minimized' : ''} ${highlight?.val ? 'highlight' : ''}`}>
        {minimizable && !fullscreend &&
          tools.minimize}
        <span className='title' style={titleStyle}>{title}</span>
        {evaluating ?
          tools.evaling
          : (hover && !minimized.val &&
            <div className='toolrow'>
              {addTools}
              {tools.fullscreen}
            </div>)
        }
        {/* {tools.fullscreen} */}
      </div>
      <div className='windowBody' style={bodyStyle}>
        {!minimized.val &&
          content}
      </div>
      {highlight?.val && 
        <div className='overlay' style={overlayStyle} />}
    </div>
  )
}
